namespace sv_e75ce87ce38f43debd5bb0620717873d;

public enum Theme
{
    Light,
    Dark,
    System
}

public record ThemeInfo
{
    public Theme Theme { get; init; } = Theme.Light;
    public string AccentColor { get; init; } = "#0d6efd";
}

@rendermode InteractiveServer

<span class="badge rounded-pill" style="background-color: @(Theme?.AccentColor ?? "#0d6efd");">
    @ThemeLabel
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeLabel => Theme?.Theme switch
    {
        Theme.Dark => "🌙 Dark",
        Theme.System => "💻 System",
        _ => "☀️ Light"
    };
}

@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme" title="Toggle theme">
    @CurrentIcon
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string CurrentIcon => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };

    private async Task CycleTheme()
    {
        var current = Theme ?? new ThemeInfo();
        var next = current.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
        await ThemeSource.NotifyChangedAsync(current with { Theme = next });
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(t == currentTheme ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SetTheme(t)">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-2 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@currentAccent" @onchange="SetAccent" />
            <span>@currentAccent</span>
        </div>

        <div class="mt-3">
            <span class="badge rounded-pill" style="background-color: @currentAccent;">
                Preview: @currentTheme
            </span>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme currentTheme;
    private string currentAccent = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task SetTheme(Theme theme)
    {
        currentTheme = theme;
        await Publish();
    }

    private async Task SetAccent(ChangeEventArgs e)
    {
        currentAccent = e.Value?.ToString() ?? "#0d6efd";
        await Publish();
    }

    private Task Publish() =>
        ThemeSource.NotifyChangedAsync(new ThemeInfo
        {
            Theme = currentTheme,
            AccentColor = currentAccent
        });
}

